#include <vector>
#include <string>

class Solution {
public:
    std::vector<int> validSequence(std::string word1, std::string word2) {
        int n = word1.size(), m = word2.size();
        std::vector<int> right(m + 1, 1e9);
        right[m] = n;

        int curr = n - 1;
        for (int j = m - 1; j >= 0; --j) {
            while (curr >= 0 && word1[curr] != word2[j]) curr--;
            if (curr >= 0) {
                right[j] = curr;
                curr--;
            } else {
                right[j] = 1e9;
            }
        }

        std::vector<int> ans;
        bool used_mismatch = false;
        int i = 0;

        for (int j = 0; j < m; ++j) {
            while (i < n && word1[i] != word2[j]) {
                if (!used_mismatch && right[j + 1] > i) break;
                i++;
            }
            if (i == n) return {};
            if (word1[i] != word2[j]) used_mismatch = true;
            ans.push_back(i);
            i++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] validSequence(String word1, String word2) {
        int n = word1.length(), m = word2.length();
        int[] right = new int[m + 1];
        Arrays.fill(right, (int) 1e9);
        right[m] = n;

        int curr = n - 1;
        for (int j = m - 1; j >= 0; j--) {
            while (curr >= 0 && word1.charAt(curr) != word2.charAt(j)) curr--;
            if (curr >= 0) {
                right[j] = curr;
                curr--;
            } else {
                right[j] = (int) 1e9;
            }
        }

        int[] ans = new int[m];
        boolean usedMismatch = false;
        int i = 0;

        for (int j = 0; j < m; j++) {
            while (i < n && word1.charAt(i) != word2.charAt(j)) {
                if (!usedMismatch && right[j + 1] > i) break;
                i++;
            }
            if (i == n) return new int[0];
            if (word1.charAt(i) != word2.charAt(j)) usedMismatch = true;
            ans[j] = i;
            i++;
        }
        return ans;
    }
}

var validSequence = function(word1, word2) {
    const n = word1.length, m = word2.length;
    const right = new Int32Array(m + 1).fill(1e9);
    right[m] = n;

    let curr = n - 1;
    for (let j = m - 1; j >= 0; j--) {
        while (curr >= 0 && word1[curr] !== word2[j]) curr--;
        if (curr >= 0) {
            right[j] = curr;
            curr--;
        } else {
            right[j] = 1e9;
        }
    }

    const ans = [];
    let usedMismatch = false;
    let i = 0;

    for (let j = 0; j < m; j++) {
        while (i < n && word1[i] !== word2[j]) {
            if (!usedMismatch && right[j + 1] > i) break;
            i++;
        }
        if (i === n) return [];
        if (word1[i] !== word2[j]) usedMismatch = true;
        ans.push(i);
        i++;
    }
    return ans;
};
